/* Browser UI. All content is local, escaped before HTML insertion, and versioned in JSON. */
const D = JSON.parse(document.getElementById('atlas-data').textContent);
const L = D.locales;
let storage;
try { storage=window.localStorage; } catch { storage=null; }
const prefs=readStorage(storage,'lift-atlas:prefs',{});
const state={lang:Object.hasOwn(L,prefs.lang)?prefs.lang:'zh-CN',theme:prefs.theme==='dark'?'dark':'light',query:'',eqQuery:'',category:'all',pattern:'all',place:'all',eqLimit:24,selected:new Set(),tableSort:'name',goal:'hypertrophy',profile:{age:'',goal:'hypertrophy',days:2,minutes:50,level:'beginner',place:'home',urgent:'unknown',health:'unknown',equipment:[]},recommended:null};
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const tr=k=>L[state.lang][k]??L.en[k]??k;
const tx=v=>text(v,state.lang);
const b=(z,en)=>state.lang.startsWith('zh')?z:en;
const h=escapeHTML;
const cat=id=>D.categories.find(x=>x.id===id);
const eq=id=>D.equipment.find(x=>x.id===id);
const exr=id=>D.exercises.find(x=>x.id===id);
const sourceBy=id=>D.sources.find(x=>x.id===id);
const label=(id)=>({low:b('较低','Lower'),moderate:b('中等','Moderate'),high:b('较高','Higher'),pocket:b('便携','Portable'),small:b('小','Small'),medium:b('中','Medium'),large:b('大','Large'),self:b('自主控制路径','User-controlled path'),guided:b('器械导向','Machine-guided'),cyclic:b('周期路径','Cyclic path'),support:b('辅助 / 支撑','Support'),measurement:b('测量','Measurement'),resistance:b('抗阻训练','Resistance'),aerobic:b('有氧训练','Aerobic'),conditioning:b('体能训练','Conditioning'),recovery:b('恢复辅助','Recovery support'),home:tr('homePlace'),gym:tr('gymPlace'),outdoor:tr('outdoorPlace'),beginner:tr('beginner'),intermediate:tr('intermediate')})[id]||id;
const regions={legs:['腿部','Legs'],glutes:['臀部','Glutes'],posterior:['后侧链','Posterior chain'],chest:['胸部','Chest'],arms:['上肢','Arms'],back:['背部','Back'],shoulders:['肩部','Shoulders'],trunk:['躯干','Trunk'],hips:['髋周','Hips'],calves:['小腿','Calves'],'full-body':['全身','Whole body'],varies:['随动作变化','Varies by exercise'],'not-applicable':['不适用','Not applicable']};
const regionText=id=>regions[id]?b(...regions[id]):id;
let layerNames={foundation:b('通识与目标','Foundations'),training:b('抗阻与有氧','Training'),nutrition:b('营养与体重管理','Nutrition'),metrics:b('测量与解释','Measurement'),recovery:b('疲劳与恢复','Recovery'),rehab:b('损伤与康复边界','Rehabilitation boundaries'),population:b('人群适配','Population adaptation')};
const svg=id=>D.images[id]||D.images.free;
const icon=(i)=>['◌','▧','⇄','▤','▥','⌁','◎','▦','◈'][i];
function chip(s,cls=''){return `<span class="chip ${cls}">${h(s)}</span>`;}
function tags(xs){return `<div class="tags">${xs.map(x=>chip(x)).join('')}</div>`;}
function sourceLinks(ids){return `<div class="source-links">${ids.map(id=>{const s=sourceBy(id);return s?`<a href="${h(safeURL(s.url))}" target="_blank" rel="noopener noreferrer" title="${h(s.title)}">${h(s.publisher.split(' / ')[0])}${s.year?' · '+s.year:''}<span aria-hidden="true"> ↗</span></a>`:'';}).join('')}</div>`;}
function sourceBlock(ids,scope){return `<section class="source-block"><h3>${h(tr('sources'))}</h3>${scope?`<p>${h(tx(scope))}</p>`:''}${sourceLinks(ids)}<p class="small muted">${h(b('多个文档可能共享研究，不自动视为独立重复验证。已做案头交叉核对；尚无持证专家签署。','Documents may share underlying studies; they are not automatically independent replications. Desk cross-check completed; no licensed-expert sign-off.'))}</p></section>`;}
function sectionHead(eyebrow,title,desc,action=''){return `<div class="section-head"><div><p class="eyebrow">${h(eyebrow)}</p><h1>${h(title)}</h1>${desc?`<p class="lead">${h(desc)}</p>`:''}</div>${action}</div>`;}
function empty(message=tr('noResults')){return `<div class="empty"><span aria-hidden="true">⌕</span><h3>${h(message)}</h3><p>${h(b('缩短关键词或放宽非安全限制；安全条件不会自动放宽。','Shorten the query or relax non-safety constraints. Safety conditions are never relaxed automatically.'))}</p></div>`;}
function notice(txt,type='info'){return `<div class="notice ${type}" role="${type==='danger'?'alert':'note'}">${h(txt)}</div>`;}
function savePrefs(){writeStorage(storage,'lift-atlas:prefs',{lang:state.lang,theme:state.theme});}
function shell(){
  document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';document.documentElement.dataset.theme=state.theme;
  const names=['home','equipment','compare','plans','knowledge','methods','populations','metrics','evidence'];
  const page=(location.hash.slice(1).split('/')[0]||'home');
  $('#shell').innerHTML=`<aside class="sidebar"><a class="brand" href="#home"><span class="brand-mark" aria-hidden="true">L<span>↗</span></span><span>Lift Atlas<small>${h(b('循证健身图谱','Evidence-informed fitness'))}</small></span></a><p class="nav-label">${h(b('训练，从理解开始','TRAIN WITH UNDERSTANDING'))}</p><nav aria-label="${h(b('主导航','Main navigation'))}">${names.map((x,i)=>`<a href="#${x}" ${page===x?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon(i)}</span>${h(tr(x))}${x==='compare'?`<span class="count">${state.selected.size}</span>`:''}</a>`).join('')}</nav><div class="sidebar-note"><span class="dot"></span> ${h(b('离线可读 · 无广告','Offline-ready · No ads'))}<p>${h(b('公开依据，不制造确定性。','Open sources, honest uncertainty.'))}</p><small>v${h(D.meta.version)} · ${h(D.meta.reviewedAt)}</small></div></aside><div class="workspace"><header class="topbar"><a class="mobile-brand" href="#home">Lift Atlas</a><form id="global-form" class="global-search" role="search"><span aria-hidden="true">⌕</span><input id="global-query" aria-label="${h(tr('search'))}" placeholder="${h(tr('searchHint'))}" value="${h(state.query)}" maxlength="240"><button type="submit" aria-label="${h(tr('search'))}">↵</button></form><div class="top-actions"><select id="language" aria-label="${h(tr('language'))}">${Object.keys(L).map(lang=>`<option value="${lang}" ${lang===state.lang?'selected':''}>${({'zh-CN':'简体中文','zh-TW':'繁體中文',en:'English',es:'Español',fr:'Français',de:'Deutsch',pt:'Português',ja:'日本語',ko:'한국어',ru:'Русский',ar:'العربية',hi:'हिन्दी'})[lang]}</option>`).join('')}</select><button id="theme" class="icon-button" aria-label="${h(tr('theme'))}">${state.theme==='light'?'☾':'☀'}</button></div></header><nav class="mobile-nav" aria-label="${h(b('移动导航','Mobile navigation'))}">${names.map(x=>`<a href="#${x}" ${page===x?'aria-current="page"':''}>${h(tr(x))}</a>`).join('')}</nav><div id="language-notice">${!['zh-CN','en'].includes(state.lang)?notice(tr('fallback')):''}</div><main id="main" tabindex="-1"></main><footer><strong>Lift Atlas</strong><p>${h(tr('healthDisclaimer'))}</p><small>${h(b('资料核对','Sources checked'))} ${h(D.meta.reviewedAt)} · MIT code / CC BY 4.0 content · ${h(b('未完成临床审校签署','Clinical sign-off pending'))}</small></footer></div><div id="toast" role="status" aria-live="polite"></div><dialog id="detail-dialog"><button class="dialog-close" aria-label="${h(tr('close'))}" data-close>×</button><div id="detail-content"></div></dialog>`;
  $('#global-form').onsubmit=e=>{e.preventDefault();state.query=$('#global-query').value.trim();go('search');};
  $('#language').onchange=e=>{state.lang=e.target.value;savePrefs();render();};
  $('#theme').onclick=()=>{state.theme=state.theme==='light'?'dark':'light';savePrefs();document.documentElement.dataset.theme=state.theme;$('#theme').textContent=state.theme==='light'?'☾':'☀';};
  $('[data-close]').onclick=()=>$('#detail-dialog').close();
}
function go(hash){if(location.hash==='#'+hash)render();else location.hash=hash;}
function flash(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000);}
function home(){
  $('#main').innerHTML=`<div class="hero"><div class="hero-copy"><p class="eyebrow">LIFT ATLAS / 01</p><h1>${h(b('练得明白，','Understand your training.'))}<br><em>${h(b('再练得更好。','Then make it better.'))}</em></h1><p class="lead">${h(tr('overview'))}<br>${h(b('把器材、计划和研究放在一起。','Equipment, programs and evidence in one place.'))}</p><div class="hero-actions"><button class="primary" data-start>${h(tr('start'))}<span>↗</span></button><a class="button secondary" href="#equipment">${h(tr('browse'))}</a></div><div class="hero-proof">${chip(b('无账号','No account'))}${chip(b('不上传健康记录','No health-data upload'))}${chip(b('建议可追溯','Traceable advice'))}</div></div><div class="hero-art"><div class="art-number">01—12</div>${svg('free')}<div class="floating-label"><span class="dot"></span>${h(b('器材是工具，不是答案','Equipment is a tool, not the answer'))}</div><div class="art-caption">${h(b('原创类别示意 · 非具体型号','Original category schematic · Not a specific model'))}</div></div></div><section class="goal-grid" aria-label="${h(tr('goal'))}"><button class="goal-card muscle" data-goal="hypertrophy"><span class="goal-number">01</span><div><h2>${h(tr('muscle'))}</h2><p>${h(b('负荷 × 渐进 × 恢复','Loading × Progression × Recovery'))}</p><small>${h(b('找到能长期执行的抗阻计划','Find repeatable resistance training'))}</small></div><span class="arrow">↗</span></button><button class="goal-card fat" data-goal="fat-loss"><span class="goal-number">02</span><div><h2>${h(tr('fat'))}</h2><p>${h(b('饮食习惯 × 活动 × 肌肉保留','Food habits × Activity × Muscle retention'))}</p><small>${h(b('不追求一台机器的“燃脂排名”','No invented machine fat-loss rankings'))}</small></div><span class="arrow">↗</span></button></section><div class="stats-grid">${[[D.equipment.length,b('器材条目','Equipment types')],[D.categories.length,b('互斥主类','Primary families')],[D.plans.length,b('示例计划','Plan templates')],[D.sources.length,b('来源文档','Source documents')]].map(([n,s])=>`<div><strong>${n}</strong><span>${h(s)}</span></div>`).join('')}</div><section><div class="inline-heading"><h2>${h(b('先掌握这四件事','Four useful starting points'))}</h2><a href="#knowledge">${h(tr('all'))} →</a></div><div class="knowledge-grid">${D.knowledge.filter(x=>['two-goals','equipment-choice','protein','sleep'].includes(x.id)).map(knowledgeCard).join('')}</div></section><section><div class="inline-heading"><h2>${h(b('器材不是一条排行榜','Equipment is not one leaderboard'))}</h2><a href="#compare">${h(tr('compare'))} →</a></div><div class="family-grid">${D.categories.map(c=>`<button class="family-card" data-family="${c.id}"><div>${svg(c.id)}</div><strong>${h(tx(c.name))}</strong><small>${D.equipment.filter(x=>x.category===c.id).length} ${h(b('条目','types'))}</small></button>`).join('')}</div></section>${notice(b(`“日常器材95%覆盖”是待抽样验证的目标，不是目前已测得的结论。这里收录${D.equipment.length}类器材，不声称覆盖所有品牌型号。`,`95% everyday-equipment coverage is a target awaiting sample validation, not a measured result. This catalog contains ${D.equipment.length} types, not every branded model.`))}`;
  $('[data-start]').onclick=()=>go('plans');
  $$('[data-goal]').forEach(el=>el.onclick=()=>{state.goal=state.profile.goal=el.dataset.goal;state.recommended=null;go('plans');});
  $$('[data-family]').forEach(el=>el.onclick=()=>{state.category=el.dataset.family;go('equipment');});
  bindKnowledge();
}
function knowledgeCard(k){return `<article class="knowledge-card"><div class="card-eyebrow">${h(layerNames[k.layer]||k.layer)}<span>${k.sources.length} ${h(b('来源文档','documents'))}</span></div><h3><button class="text-link" data-knowledge="${k.id}">${h(tx(k.title))}</button></h3><p>${h(tx(k.summary))}</p><button class="read-link" data-knowledge="${k.id}">${h(tr('reading'))} →</button></article>`;}
function bindKnowledge(){$$('[data-knowledge]').forEach(el=>el.onclick=()=>showKnowledge(el.dataset.knowledge));}
function openDialog(content){$('#detail-content').innerHTML=content;$('#detail-dialog').showModal();}
function showKnowledge(id){const k=D.knowledge.find(x=>x.id===id);if(!k)return;openDialog(`<p class="eyebrow">${h(layerNames[k.layer])} / ${h(k.id)}</p><h2>${h(tx(k.title))}</h2><p class="detail-lead">${h(tx(k.summary))}</p><div class="takeaway"><h3>${h(b('怎么做','What to do'))}</h3><p>${h(tx(k.action))}</p></div><h3>${h(b('适用范围与例外','Scope and exceptions'))}</h3><p>${h(tx(k.scope))}</p>${k.auditLabel?notice(tx(k.auditLabel)):''}<section class="source-block"><h3>${h(b('这些来源分别支持什么？','What does each source support?'))}</h3>${(k.sourceRoles||[]).map(r=>`<p><strong>${h(sourceBy(r.source)?.publisher||r.source)}</strong><br>${h(tx(r.role))}</p>`).join('')}</section>${sourceBlock(k.sources)}<p class="small muted">${h(k.reviewStatus)} · ${k.checked}</p>`);}
function filteredEquipment(){return searchItems(D.equipment,state.eqQuery,999).filter(x=>(state.category==='all'||x.category===state.category)&&(state.pattern==='all'||x.patterns.includes(state.pattern))&&(state.place==='all'||x.settings.includes(state.place)));}
function equipment(){
  $('#main').innerHTML=sectionHead('EQUIPMENT ATLAS',tr('equipment'),b('按结构归类，按任务查找。每种器材都标明用途、限制和替代方向。','Classified by structure, searched by task. Each type states uses, limits and potential alternatives.'),`<a class="button secondary" href="#compare">${h(tr('fullTable'))} →</a>`)+`<div class="filters"><label class="search-filter"><span>${h(tr('search'))}</span><input id="eq-search" placeholder="${h(tr('searchHint'))}" value="${h(state.eqQuery)}" maxlength="160"></label><label><span>${h(tr('family'))}</span><select id="category-filter"><option value="all">${h(tr('all'))}</option>${D.categories.map(c=>`<option value="${c.id}" ${c.id===state.category?'selected':''}>${h(tx(c.name))}</option>`).join('')}</select></label><label><span>${h(tr('pattern'))}</span><select id="pattern-filter"><option value="all">${h(tr('all'))}</option>${Object.entries(D.patterns).map(([id,p])=>`<option value="${id}" ${id===state.pattern?'selected':''}>${h(tx(p))}</option>`).join('')}</select></label><label><span>${h(tr('place'))}</span><select id="place-filter"><option value="all">${h(tr('all'))}</option>${['home','gym','outdoor'].map(id=>`<option value="${id}" ${id===state.place?'selected':''}>${h(label(id))}</option>`).join('')}</select></label></div><p class="small muted">${h(b('图片为12类原创SVG示意，不是每款设备的精确外观或使用教程。','Images are 12 original category SVGs, not precise drawings or operating instructions for every device.'))}</p><div id="equipment-results"></div>`;
  $('#eq-search').oninput=e=>{state.eqQuery=e.target.value;state.eqLimit=24;equipmentResults();};
  for(const [id,key] of [['category-filter','category'],['pattern-filter','pattern'],['place-filter','place']])$('#'+id).onchange=e=>{state[key]=e.target.value;state.eqLimit=24;equipmentResults();};
  equipmentResults();
}
function equipmentResults(){
  const items=filteredEquipment();$('#equipment-results').innerHTML=`<div class="result-heading"><span>${items.length} / ${D.equipment.length} ${h(b('条目','types'))}</span><a href="#compare">${h(tr('selected'))} ${state.selected.size} →</a></div><div class="equipment-grid">${items.slice(0,state.eqLimit).map(e=>`<article class="equipment-card"><button class="equipment-image" data-eq="${e.id}" aria-label="${h(tx(e.name))}">${svg(e.category)}<span>${h(tx(cat(e.category).name))}</span></button><div class="equipment-body"><p class="latin-label">${h(e.name.en)}</p><h3><button class="text-link" data-eq="${e.id}">${h(tx(e.name))}</button></h3><p>${h(tx(e.use))}</p>${tags(e.patterns.slice(0,2).map(id=>tx(D.patterns[id])))}<div class="card-bottom"><button class="small-button ${state.selected.has(e.id)?'active':''}" data-compare="${e.id}" aria-pressed="${state.selected.has(e.id)}">${h(state.selected.has(e.id)?tr('remove'):tr('add'))}</button><button class="read-link" data-eq="${e.id}">${h(tr('details'))} ↗</button></div></div></article>`).join('')}</div>${items.length===0?empty():''}${items.length>state.eqLimit?`<button class="load-more secondary" id="load-more">${h(b('继续显示','Show more'))} (${Math.min(24,items.length-state.eqLimit)})</button>`:''}`;
  $$('[data-eq]').forEach(el=>el.onclick=()=>go('equipment/'+el.dataset.eq));
  $$('[data-compare]').forEach(el=>el.onclick=()=>toggleCompare(el.dataset.compare));
  if($('#load-more'))$('#load-more').onclick=()=>{state.eqLimit+=24;equipmentResults();};
}
function toggleCompare(id){if(!eq(id))return;if(state.selected.has(id))state.selected.delete(id);else if(state.selected.size<6)state.selected.add(id);else return flash(b('并排比较最多6项；完整表仍涵盖全部器材。','Compare up to six side by side; the full table still covers all equipment.'));
  $$('.count').forEach(el=>el.textContent=state.selected.size);
  if($('#equipment-results'))equipmentResults();else if((location.hash||'').startsWith('#compare'))compare();else renderPage();
}
function equipmentDetail(id){const e=eq(id);if(!e){$('#main').innerHTML=empty(b('未找到器材ID','Equipment ID not found'));return;}
  $('#main').innerHTML=`<a class="back-link" href="#equipment">← ${h(tr('equipment'))}</a><div class="detail-header"><div class="detail-image">${svg(e.category)}<small>${h(b('类别示意，不是该型号实物图','Category schematic, not a model image'))}</small></div><div><p class="eyebrow">${h(e.id)} / ${h(tx(cat(e.category).name))}</p><h1>${h(tx(e.name))}</h1><p class="latin-label">${h(e.name.en)}</p><p class="detail-lead">${h(tx(e.use))}</p>${tags(e.patterns.map(id=>tx(D.patterns[id])))}<button class="primary" id="detail-compare">${h(state.selected.has(id)?tr('remove'):tr('add'))}</button></div></div><div class="two-columns"><section class="panel"><h2>${h(b('结构与用途','Structure and use'))}</h2><dl>${[[tr('family'),tx(cat(e.category).name)],[tr('pattern'),e.patterns.map(id=>tx(D.patterns[id])).join(' / ')],[b('主要区域','Main regions'),e.regions.map(regionText).join(' / ')],[b('训练角色','Training role'),label(e.role)],[b('运动路径','Movement path'),label(e.path)],[tr('place'),e.settings.map(label).join(' / ')],[tr('level'),label(e.learning)],[tr('footprint'),label(e.footprint)]].map(([k,v])=>`<div><dt>${h(k)}</dt><dd>${h(v)}</dd></div>`).join('')}</dl><p class="small muted">${h(b('学习要求、占地为编辑的类型级定性判断，不是风险分数或厂商尺寸。使用空间还取决于动作、身体尺寸和安全余量。','Learning and space are qualitative type-level editorial judgments, not risk scores or manufacturer dimensions. Exercise, body size and clearance change space needs.'))}</p></section><section class="panel"><h2>${h(tr('caution'))}</h2><p class="detail-lead">${h(tx(e.caution))}</p>${notice(b('先核对具体型号手册、调节方式、额定承重和维护状态。器材名称不保证适合某种疼痛或疾病。','Check the exact model manual, adjustments, ratings and maintenance. A device name does not establish suitability for a painful condition or disease.'))}<h3>${h(b('替代方向，不是等效处方','Alternative directions, not equivalent prescriptions'))}</h3><div class="alternative-list">${e.alternatives.length?e.alternatives.map(id=>`<a href="#equipment/${id}">${h(tx(eq(id).name))} ↗</a>`).join(''):`<p class="muted">${h(b('辅助或测量工具不强行推荐训练替代品。','No forced training substitute for a support or measurement tool.'))}</p>`}</div><p class="small muted">${h(b('仅按角色和动作交集筛选，不能保证相同肌肉刺激、关节耐受或适合康复。','Filtered by role and movement overlap; not a guarantee of identical stimulus, tolerance or rehabilitation suitability.'))}</p></section></div>${sourceBlock(e.sources,e.evidenceScope)}<p class="small muted">${h(e.reviewStatus)}</p>`;
  $('#detail-compare').onclick=()=>toggleCompare(id);
}
function comparisonColumns(){return [{label:tr('equipment'),value:e=>tx(e.name)},{label:tr('family'),value:e=>tx(cat(e.category).name)},{label:tr('pattern'),value:e=>e.patterns.map(id=>tx(D.patterns[id])).join(' / ')},{label:b('训练角色','Role'),value:e=>label(e.role)},{label:b('路径','Path'),value:e=>label(e.path)},{label:tr('level'),value:e=>label(e.learning)},{label:tr('footprint'),value:e=>label(e.footprint)},{label:tr('place'),value:e=>e.settings.map(label).join(' / ')},{label:tr('use'),value:e=>tx(e.use)},{label:tr('caution'),value:e=>tx(e.caution)},{label:b('证据范围','Evidence scope'),value:e=>tx(e.evidenceScope)},{label:'id',value:'id'}];}
function download(name,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function compare(){
  const selected=[...state.selected].map(eq).filter(Boolean);const rows=[...D.equipment].sort((a,c)=>state.tableSort==='family'?a.category.localeCompare(c.category)||tx(a.name).localeCompare(tx(c.name)):tx(a.name).localeCompare(tx(c.name),state.lang));
  const axes=[[tr('family'),e=>tx(cat(e.category).name)],[tr('pattern'),e=>e.patterns.map(id=>tx(D.patterns[id])).join(' / ')],[b('训练角色','Role'),e=>label(e.role)],[b('路径','Path'),e=>label(e.path)],[tr('level'),e=>label(e.learning)],[tr('footprint'),e=>label(e.footprint)],[tr('use'),e=>tx(e.use)],[tr('caution'),e=>tx(e.caution)],[b('直接优越性证据','Direct superiority evidence'),()=>b('未建立逐器材通用排名','No universal device-level ranking established')]];
  $('#main').innerHTML=sectionHead('COMPARE / NO INVENTED SCORES',tr('compare'),b('比较条件与限制，而不是给“效果”编一个总分。','Compare conditions and limitations, not an invented effectiveness score.'),`<button class="primary" id="export-equipment">${h(tr('export'))} · ${D.equipment.length}</button>`)+notice(b('器材类别不同，训练角色也不同。测量、恢复和支撑工具的“增肌/减脂效果”不适用；同类器材的公斤数也未必可直接横比。','Different families serve different roles. Hypertrophy/fat-loss effectiveness is not applicable to measuring, recovery or support tools; even loads within a family may not be directly comparable.'))+`<div class="inline-heading"><h2>${h(tr('selected'))} · ${selected.length}/6</h2><div><a href="#equipment">+ ${h(tr('equipment'))}</a> <button class="small-button" id="clear-comparison">${h(tr('clear'))}</button></div></div>${selected.length?`<div class="table-wrap" tabindex="0" aria-label="${h(tr('compare'))}"><table class="comparison-table"><thead><tr><th>${h(b('比较维度','Dimension'))}</th>${selected.map(e=>`<th><a href="#equipment/${e.id}">${h(tx(e.name))}</a><button class="table-remove" data-remove="${e.id}" aria-label="${h(tr('remove')+' '+tx(e.name))}">×</button></th>`).join('')}</tr></thead><tbody>${axes.map(([name,fn])=>`<tr><th scope="row">${h(name)}</th>${selected.map(e=>`<td>${h(fn(e))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="small-empty">${h(b('在器材卡片上点“加入比较”，可并排查看；下面始终保留完整清单。','Select Compare on equipment cards to view them side by side. The full inventory is always available below.'))}</div>`}<div class="inline-heading"><h2>${h(tr('fullTable'))} · ${D.equipment.length}</h2><label>${h(b('排序','Sort'))}<select id="table-sort"><option value="name">${h(tr('equipment'))}</option><option value="family" ${state.tableSort==='family'?'selected':''}>${h(tr('family'))}</option></select></label></div><p class="small muted">${h(b('占地、学习要求为编辑定性分档，非测量值。完整导出包括用途、风险提示及证据适用范围。','Space and learning are editorial categories, not measured values. Export includes use, cautions and evidence scope.'))}</p><div class="table-wrap" tabindex="0"><table class="inventory-table"><thead><tr>${[tr('equipment'),tr('family'),tr('pattern'),tr('level'),tr('footprint'),tr('caution')].map(t=>`<th>${h(t)}</th>`).join('')}</tr></thead><tbody>${rows.map(e=>`<tr><th scope="row"><a href="#equipment/${e.id}">${h(tx(e.name))}</a><small>${h(e.name.en)}</small></th><td>${h(tx(cat(e.category).name))}</td><td>${h(e.patterns.map(id=>tx(D.patterns[id])).join(' / '))}</td><td>${h(label(e.learning))}</td><td>${h(label(e.footprint))}</td><td>${h(tx(e.caution))}</td></tr>`).join('')}</tbody></table></div>`;
  $('#export-equipment').onclick=()=>download('lift-atlas-equipment.csv',toCSV(rows,comparisonColumns()),'text/csv;charset=utf-8');
  $('#clear-comparison').onclick=()=>{state.selected.clear();render();};
  $$('[data-remove]').forEach(el=>el.onclick=()=>toggleCompare(el.dataset.remove));
  $('#table-sort').onchange=e=>{state.tableSort=e.target.value;compare();};
}
const gateText=()=>({urgent:b('停止训练建议匹配。出现胸痛、晕厥、进行性神经症状或其他严重异常，应及时联系当地急救或就医；本工具不能排除急症。','Plan matching is stopped. Chest pain, fainting, progressive neurological symptoms or other severe abnormalities warrant local emergency help or medical assessment; this tool cannot rule out an emergency.'),under18:b('未成年人：仅提供教育资料，不生成成人增肌或减脂处方。','Under 18: educational resources only, not adult hypertrophy or fat-loss prescriptions.'),older:b('65岁以上：本版仅提供人群教育与专业适配入口；不是建议停止活动。','Age 65+: this release provides population guidance and professional adaptation, not advice to stop activity.'),age:b('先填写有效年龄；本版自动模板适用范围为18–64岁。','Enter a valid age first. Automatic templates cover ages 18–64.'),screen:b('先回答两项安全问题。未回答不等于无风险。','Answer both safety questions first. Missing answers do not mean no risk.'),constraints:b('请检查目标、可用时间、场景与经验输入。','Check goal, available time, setting and experience.'),review:b('当前条件或查询触发专业评估分流：不生成个体训练建议。可阅读人群适配、康复边界及证据。','Your context or query requires professional assessment: no individual training recommendation is generated. Read population guidance, rehabilitation boundaries and evidence.')});
function gateMessage(gate){return gateText()[gate.reason]||gateText().review;}
function profileForm(){const p=state.profile;return `<form id="plan-form" class="profile-panel"><div class="inline-heading"><div><p class="eyebrow">MATCH, NOT DIAGNOSE</p><h2>${h(tr('start'))}</h2></div>${chip(b('无需注册','No registration'))}</div><p class="small muted">${h(b('只匹配已有模板，不生成医疗处方。所有信息仅留在当前页面；不会上传或自动保存健康档案。','Matches existing templates, not medical prescriptions. Inputs stay in this page; no upload or automatic health-profile storage.'))}</p><div class="form-grid"><label>${h(tr('goal'))}<select name="goal">${[['hypertrophy',tr('muscle')],['fat-loss',tr('fat')]].map(([id,n])=>`<option value="${id}" ${p.goal===id?'selected':''}>${h(n)}</option>`).join('')}</select></label><label>${h(tr('age'))}<input name="age" type="number" min="1" max="120" value="${h(p.age)}" placeholder="18–64" required></label><label>${h(tr('days'))}<select name="days">${[2,3,4,5,6,7].map(n=>`<option ${Number(p.days)===n?'selected':''}>${n}</option>`).join('')}</select></label><label>${h(tr('minutes'))}<select name="minutes">${[20,30,40,45,50,55,60,75,90].map(n=>`<option ${Number(p.minutes)===n?'selected':''}>${n}</option>`).join('')}</select></label><label>${h(tr('place'))}<select name="place">${['home','gym','outdoor'].map(id=>`<option value="${id}" ${p.place===id?'selected':''}>${h(label(id))}</option>`).join('')}</select></label><label>${h(b('训练经验','Experience'))}<select name="level">${['beginner','intermediate'].map(id=>`<option value="${id}" ${p.level===id?'selected':''}>${h(label(id))}</option>`).join('')}</select></label></div><div class="safety-fields"><label>${h(b('现在有胸痛、晕厥、严重气短、明显神经症状或其他紧急异常吗？','Do you currently have chest pain, fainting, severe breathlessness, significant neurological symptoms or another urgent abnormality?'))}<select name="urgent">${[['unknown',b('请选择','Select an answer')],['no',b('没有已知的上述症状','No known symptoms above')],['yes',b('有 / 可能有','Yes / possibly')]].map(([id,n])=>`<option value="${id}" ${p.urgent===id?'selected':''}>${h(n)}</option>`).join('')}</select></label><label>${h(b('是否有影响训练的疼痛、伤病、慢性病、孕产期或其他限制？','Any pain, injury, chronic illness, pregnancy/postpartum status or other limitation affecting training?'))}<select name="health">${[['unknown',b('请选择 / 不确定','Select / unsure')],['healthy',b('没有已知限制（不是医学体检结论）','No known limitation (not medical clearance)')],['pain',b('疼痛、损伤或术后','Pain, injury or postoperative')],['chronic',b('慢性疾病或运动相关用药','Chronic condition or exercise-related medication')],['pregnancy',b('孕期或产后','Pregnancy or postpartum')],['disability',b('需要活动或无障碍适配','Needs mobility / access adaptation')],['eating',b('进食障碍风险或体重追踪引发不适','Eating-disorder risk or distress from tracking')]].map(([id,n])=>`<option value="${id}" ${p.health===id?'selected':''}>${h(n)}</option>`).join('')}</select></label></div><details class="equipment-picker"><summary>${h(b('我实际能使用的器材','Equipment I can actually use'))} <span id="available-count">(${p.equipment.length})</span></summary><p class="small muted">${h(b('预设仅勾选清单，仍需你核实；“在健身房”不等于拥有全部器材。','Presets only check inventory boxes; verify them. Being at a gym does not imply access to every machine.'))}</p><div class="preset-buttons">${[['none',b('清空','Clear')],['db',b('一对哑铃','Dumbbells')],['band',b('长环形弹力带','Long loop band')],['machine',b('常见器械组合','Common machine set')]].map(([id,t])=>`<button type="button" class="small-button" data-preset="${id}">${h(t)}</button>`).join('')}</div>${D.categories.map(c=>`<fieldset><legend>${h(tx(c.name))}</legend><div class="check-grid">${D.equipment.filter(e=>e.category===c.id).map(e=>`<label><input type="checkbox" name="equipment" value="${e.id}" ${p.equipment.includes(e.id)?'checked':''}>${h(tx(e.name))}</label>`).join('')}</div></fieldset>`).join('')}</details><label>${h(b('补充搜索（可选，例如“减脂 3天 60分钟”）','Optional short query, e.g. “fat loss 3 days 60 min”'))}<input name="query" maxlength="240" value="${h(state.query)}" placeholder="${h(b('器材以勾选清单为准，症状词会触发分流','Equipment uses the checklist; symptom terms trigger assessment'))}"></label><button class="primary" type="submit">${h(tr('recommend'))} →</button><p class="small muted">${h(b('文本中的时间只会收紧约束；否定词不用于安全放行。没有专用否定语义分析，有症状字样仍可能保守拦截。','Time in text only tightens limits. Negation is not used for safety clearance; symptom terms may conservatively block even a negated phrase.'))}</p></form>`;}
function planCard(p,matched=false){return `<article class="plan-card"><div class="card-eyebrow">${h(p.goal==='hypertrophy'?tr('muscle'):tr('fat'))}<span>${p.days} ${h(b('天 / 周','days / week'))}</span></div><h3><a href="#plans/${p.id}">${h(tx(p.name))}</a></h3>${tags([p.minutes+' '+b('分钟 / 次','min / session'),label(p.level),p.partial?b('不完整起步模块','Partial starter'):b('含抗阻模块','Includes resistance')])}<p>${h(tx(p.notes))}</p><div class="card-bottom"><span class="small muted">${matched?h(b('符合当前硬约束','Matches hard constraints')):h(b('公开示例，非个人处方','Public example, not a prescription'))}</span><a class="read-link" href="#plans/${p.id}">${h(tr('details'))} →</a></div></article>`;}
function plans(){
  $('#main').innerHTML=sectionHead('PLAN LIBRARY',tr('plans'),b('先确认安全与资源，再选一份能完成的计划。','Screen safety and resources, then choose something feasible.'))+profileForm()+`<section id="recommend-results" aria-live="polite"></section><section id="all-plans"><div class="inline-heading"><h2>${h(b('公开模板库','Public template library'))}</h2><span>${D.plans.length} ${h(b('示例','examples'))}</span></div>${notice(b('以下是教育示例。能打开计划不表示你已通过筛查；特殊人群不直接套用。','These are educational examples. Opening one does not mean you passed screening; special populations should not copy them unchanged.'))}<div class="plan-grid">${D.plans.map(p=>planCard(p)).join('')}</div></section>`;
  const form=$('#plan-form');const saveForm=()=>{const data=new FormData(form);state.profile={age:data.get('age'),goal:data.get('goal'),days:Number(data.get('days')),minutes:Number(data.get('minutes')),place:data.get('place'),level:data.get('level'),urgent:data.get('urgent'),health:data.get('health'),equipment:data.getAll('equipment')};state.query=String(data.get('query')||'');};
  form.onchange=()=>{saveForm();$('#available-count').textContent='('+state.profile.equipment.length+')';state.recommended=null;$('#recommend-results').innerHTML='';};
  form.onsubmit=e=>{e.preventDefault();saveForm();state.recommended=recommend(D.plans,D.exercises,state.profile,state.query);recommendResults();$('#recommend-results').scrollIntoView({behavior:'smooth',block:'start'});};
  $$('[data-preset]').forEach(el=>el.onclick=()=>{const sets={none:[],db:['dumbbell'],band:['loop-band'],machine:['chest-press','shoulder-press','seated-row','lat-pulldown','stack-leg-press','seated-leg-curl','upright-bike']};const selected=sets[el.dataset.preset];$$('input[name="equipment"]',form).forEach(cb=>cb.checked=selected.includes(cb.value));saveForm();$('#available-count').textContent='('+selected.length+')';state.recommended=null;$('#recommend-results').innerHTML='';});
  if(state.recommended)recommendResults();
}
function recommendResults(){const r=state.recommended;if(!r)return;
  const target=$('#recommend-results');
  if(r.gate.status!=='eligible'){target.innerHTML=notice(gateMessage(r.gate),r.gate.status==='urgent'?'danger':'warn')+`<p><a href="#populations">${h(tr('populations'))} →</a> · <a href="#knowledge">${h(tr('knowledge'))} →</a></p>`;return;}
  const why={days:b('天数不足','Insufficient days'),minutes:b('每次时长不足','Insufficient session time'),place:b('场景不匹配','Setting mismatch'),level:b('经验要求不符','Experience mismatch'),equipment:b('缺少所需器材','Required equipment missing')};
  target.innerHTML=`<div class="inline-heading"><h2>${h(b('匹配结果','Matching results'))} · ${r.results.length}</h2>${chip(b('规则透明，不是医学许可','Transparent rules, not medical clearance'))}</div>${r.results.length?`<p>${h(b('以下模板同时满足目标、时间、场景、经验与器材条件。排序优先非缺项模板，再考虑频率贴合；不代表疗效排名。','These templates satisfy goal, time, setting, experience and equipment constraints. Non-partial templates come first, then frequency fit; ordering is not an efficacy ranking.'))}</p><div class="plan-grid">${r.results.map(x=>planCard(x.plan,true)).join('')}</div>`:empty(b('没有可直接执行的模板，不强行推荐。','No directly feasible template. No forced recommendation.'))}<details class="excluded"><summary>${h(b('为什么其他计划没有出现？','Why were other plans excluded?'))} (${r.excluded.length})</summary>${r.excluded.map(x=>`<div><strong>${h(tx(x.plan.name))}</strong><p>${h(x.reasons.map(k=>why[k]).join(' · '))}</p>${x.missing.length?`<small>${h(b('未满足的动作器材条件：','Unmet exercise-equipment requirements: '))}${x.missing.map(id=>h(tx(exr(id).name))).join(' / ')}</small>`:''}</div>`).join('')}</details>`;
}
function planDetail(id){const p=D.plans.find(x=>x.id===id);if(!p){$('#main').innerHTML=empty();return;}
  const g=safetyGate(state.profile,state.query);
  $('#main').innerHTML=`<a class="back-link" href="#plans">← ${h(tr('plans'))}</a>`+sectionHead('PUBLIC TEMPLATE / NOT A PRESCRIPTION',tx(p.name),tx(p.notes),`<button id="print-plan" class="secondary">${h(tr('print'))}</button>`)+notice(b('这是公开教育模板，不是对你的训练许可。先在“训练计划”页面填写筛查与实际器材。','This is a public educational template, not clearance to train. Complete screening and equipment inventory on the Plans page.'),'warn')+(g.status==='urgent'?notice(gateMessage(g),'danger'):'')+tags([p.days+' '+b('天 / 周','days / week'),p.minutes+' '+b('分钟 / 次（含热身与列出的有氧）','min / session (warm-up and listed cardio included)'),label(p.level)])+`<div class="takeaway"><h3>${h(b('开始前','Before starting'))}</h3><p>${h(tx(p.warmup))}</p><p>${h(b('组数为每个动作的工作组；单侧动作左右各完成表中组数和次数，完成两侧后按表休息，必要时换侧间短休。RIR为还可完成次数，不要求准确到小数。','Sets are work sets per exercise. For unilateral work, complete the listed sets and reps on each side; rest as listed after both sides, with a brief pause between sides if needed. RIR estimates remaining possible reps, not an exact decimal.'))}</p></div><div class="sessions">${p.sessions.map((s,index)=>`<section class="panel"><div class="inline-heading"><h2>${h(b('第','Session '))}${index+1}${h(b('次',''))} · ${h(s.label)}</h2><span>${h(b('先热身','Warm up first'))}</span></div>${s.exercises.length?`<div class="table-wrap"><table><thead><tr>${[b('动作','Exercise'),b('组 × 次','Sets × reps'),'RIR',b('组间休息','Rest'),b('器材条件（或）','Equipment options (OR)')].map(t=>`<th>${h(t)}</th>`).join('')}</tr></thead><tbody>${s.exercises.map(r=>{const x=exr(r.exercise);return `<tr><th scope="row"><button class="text-link" data-exercise="${x.id}">${h(tx(x.name))}</button></th><td>${r.sets} × ${h(r.reps.replace(' / side',b(' / 侧',' / side')))}</td><td>${h(r.rir)}</td><td>${r.restSeconds} ${h(b('秒','sec'))}</td><td>${x.equipmentOptions.map(opt=>opt.length?opt.map(id=>`<a href="#equipment/${id}">${h(tx(eq(id).name))}</a>`).join(' + '):h(b('无需器材（仍需合适空间）','No equipment; suitable space still needed'))).join('<br> / ')}</td></tr>`;}).join('')}</tbody></table></div>`:''}${s.cardioMinutes?`<div class="cardio-strip"><strong>${h(tx(exr(s.cardioExercise).name))} · ${s.cardioMinutes} ${h(b('分钟','minutes'))}</strong><p>${h(tx(exr(s.cardioExercise).cue))}</p></div>`:''}</section>`).join('')}</div><div class="two-columns"><section class="panel"><h2>${h(b('如何进阶','Progression'))}</h2><p>${h(tx(p.progression))}</p></section><section class="panel"><h2>${h(b('停止与回退','Stop and regress'))}</h2><p>${h(tx(p.stop))}</p></section></div>${sourceBlock(p.sources,p.evidenceScope)}<p class="small muted">${h(p.reviewStatus)}</p>`;
  $('#print-plan').onclick=()=>window.print();
  $$('[data-exercise]').forEach(el=>el.onclick=()=>{const x=exr(el.dataset.exercise);openDialog(`<p class="eyebrow">${h(tx(D.patterns[x.pattern]))}</p><h2>${h(tx(x.name))}</h2><p class="detail-lead">${h(tx(x.cue))}</p>${notice(b('简要提示不能替代现场动作教学。先轻负荷练习，疼痛或无法控制时停止。','Brief cues do not replace in-person instruction. Practice lightly; stop if painful or uncontrolled.'))}${sourceBlock(x.sources,{en:'These sources support broad training principles, not validation of this exact cue sequence.','zh-CN':'来源支持一般训练原则，不表示这组动作提示本身经过临床验证。'})}`);});
}
function knowledge(){
  $('#main').innerHTML=sectionHead('KNOWLEDGE / ACTION / LIMITS',tr('knowledge'),b('每条先说结论，再给行动与适用边界。专业不等于堆满术语。','A conclusion, an action and a boundary for every card.'))+`<div class="layer-links">${Object.entries(layerNames).map(([id,t])=>`<a href="#layer-${id}">${h(t)}</a>`).join('')}</div>${Object.entries(layerNames).map(([id,t])=>`<section id="layer-${id}" class="knowledge-section"><div class="inline-heading"><h2>${h(t)}</h2><span>${D.knowledge.filter(k=>k.layer===id).length}</span></div><div class="knowledge-grid">${D.knowledge.filter(k=>k.layer===id).map(knowledgeCard).join('')}</div></section>`).join('')}`;
  // In-page section links deliberately do not overwrite application routes.
  $$('.layer-links a').forEach(a=>a.onclick=e=>{e.preventDefault();$(a.getAttribute('href')).scrollIntoView({behavior:'smooth'});});bindKnowledge();
}
function methods(){
  $('#main').innerHTML=sectionHead('METHODS ≠ EQUIPMENT',tr('methods'),b('训练方法是组织负荷的方式，不是器材分类，也不是高级越有效。','Methods organize loading; they are not equipment categories or an automatic ladder of effectiveness.'))+`<div class="knowledge-grid">${D.methods.map(m=>`<article class="knowledge-card"><p class="eyebrow">${h(m.id)}</p><h2>${h(tx(m.name))}</h2><p>${h(tx(m.definition))}</p><div class="takeaway compact">${h(tx(m.use))}</div>${sourceLinks(m.sources)}<small class="muted">${h(b('编辑定义与应用边界；来源不证明此法优于传统训练。','Editorial definition and boundaries; sources do not establish superiority over conventional training.'))}</small></article>`).join('')}</div>`;
}
function populations(){
  $('#main').innerHTML=sectionHead('ADAPT THE PERSON, NOT THE LABEL',tr('populations'),b('同一个目标，不同的起点。特殊人群先考虑安全、功能与可达性。','One goal, different starting points. Prioritize safety, function and access.'))+notice(b('此页是适配路线图，不是疾病处方库。年龄、怀孕、疾病、药物、近期损伤与功能限制可以叠加，不能用一个标签替代完整评估。','This is an adaptation map, not a disease-prescription library. Age, pregnancy, disease, medication, injury and function can overlap; one label cannot replace assessment.'))+`<div class="population-grid">${D.populations.map((g,i)=>`<article class="population-card"><span class="goal-number">${String(i+1).padStart(2,'0')}</span><h2>${h(tx(g.name))}</h2><p>${h(tx(g.advice))}</p><div class="alternative-list">${g.knowledge.map(id=>`<button class="read-link" data-knowledge="${id}">${h(tx(D.knowledge.find(k=>k.id===id).title))} →</button>`).join('')}</div>${chip(g.route==='education-only'?b('教育 / 专业适配','Education / professional adaptation'):b('先完成安全筛查','Screen first'))}</article>`).join('')}</div>`;bindKnowledge();
}
function evidence(){
  $('#main').innerHTML=sectionHead('EVIDENCE, NOT AUTHORITY THEATER',tr('evidence'),b('多个链接不等于多份独立证据。事实、推断与编辑决策分开标注。','Multiple links are not multiple independent evidence streams. Separate findings, inference and editorial choices.'))+`<div class="two-columns"><section class="panel"><h2>${h(b('本版做了什么','What this release did'))}</h2><p>${h(b('核对官方指南、论文书目信息和可获取摘要/文本，交叉检查关键训练与安全建议。对底层研究重叠、器材证据外推和特殊人群适用性保留限制说明。','Checked official guidance, bibliographic records and available abstracts/text, and cross-checked core training and safety advice. Limitations cover overlapping studies, equipment-level extrapolation and population applicability.'))}</p><p>${h(b('不是注册系统综述；没有重新提取所有原始试验、正式GRADE评级或持证临床专家签署。','Not a registered systematic review, re-extraction of every trial, formal GRADE rating or licensed clinical sign-off.'))}</p></section><section class="panel"><h2>${h(b('如何持续修订','How updates remain accountable'))}</h2><p>${h(b('新增或修改一项建议时，提交来源、适用范围、差异和复核记录。资料变新只触发复核，不自动改写训练结论。','For each changed claim, submit sources, scope, differences and review notes. New literature triggers review rather than automatically rewriting training conclusions.'))}</p><p>${h(b('器材类型级结构由编辑分类；具体型号手册、安全性和尺寸需另查。','Type-level mechanics are editorial classifications; model manuals, safety and dimensions require separate checks.'))}</p></section></div><div class="inline-heading"><h2>${h(b('来源登记册','Source register'))} · ${D.sources.length}</h2><button id="export-sources" class="secondary">${h(tr('export'))}</button></div><div class="source-register">${D.sources.map((s,i)=>`<article><span class="source-number">${String(i+1).padStart(2,'0')}</span><div><div class="tags">${chip(s.type)}${s.year?chip(s.year):''}</div><h3><a href="${h(safeURL(s.url))}" target="_blank" rel="noopener noreferrer">${h(s.title)} ↗</a></h3><p>${h(s.publisher)}</p><p class="small">${h(s.scope)}</p>${s.overlap?notice(s.overlap):''}<div class="source-meta"><code>${h(s.id)}</code><span>${h(s.access)}</span><span>${h(b('核对','Checked'))} ${s.checked}</span>${s.doi?`<span>DOI ${h(s.doi)}</span>`:''}</div></div></article>`).join('')}</div>`;
  $('#export-sources').onclick=()=>download('lift-atlas-sources.csv',toCSV(D.sources,['id','title','publisher','year','doi','url','type','scope','access','checked','overlap'].map(k=>({label:k,value:k}))),'text/csv;charset=utf-8');
}
function getLogs(){const saved=readStorage(storage,'lift-atlas:logs',[]);if(!Array.isArray(saved))return [];return saved.slice(-3000).map(x=>validateLog(x)).filter(x=>x.valid).map(x=>x.record);}
function metrics(){
  $('#main').innerHTML=sectionHead('MEASURE WITHOUT OVERINTERPRETING',tr('metrics'),b('看多周趋势，保留测量条件。数值不是对身体的评价。','Read multi-week trends and preserve measurement conditions. Numbers are not a judgment of your body.'))+notice(b('本记录模块面向20岁及以上、非孕产期且无进食障碍风险的成人。体重追踪引发焦虑时应停用。BMI仅算数值、不作诊断；不提供热量赤字处方。','This tracker is for adults aged 20+, not in pregnancy/postpartum and without eating-disorder risk. Stop if tracking causes distress. BMI is descriptive, not diagnostic; no calorie-deficit prescription.'))+`<div class="two-columns metrics-columns"><form id="metric-form" class="panel"><h2>${h(b('添加一条记录','Add a record'))}</h2><div class="form-grid"><label>${h(tr('age'))}<input name="metricAge" type="number" min="20" max="120" required value="${h(state.profile.age)}"></label><label>${h(b('日期','Date'))}<input name="date" type="date" value="${localDate()}" max="${localDate()}" required></label><label>${h(b('体重（kg，可空）','Weight (kg, optional)'))}<input name="weight" type="number" min="20" max="500" step="0.1"></label><label>${h(b('腰围（cm，可空）','Waist (cm, optional)'))}<input name="waist" type="number" min="30" max="250" step="0.1"></label><label>${h(b('身高（cm，仅算BMI，不保存）','Height (cm, BMI only, not stored)'))}<input name="height" type="number" min="100" max="250" step="0.1"></label><label>${h(b('睡眠（小时，可空）','Sleep (hours, optional)'))}<input name="sleepHours" type="number" min="0" max="24" step="0.1"></label></div><details open><summary>${h(b('训练表现（可选）','Training performance (optional)'))}</summary><label>${h(b('动作','Exercise'))}<select name="exercise"><option value="">${h(tr('none'))}</option>${D.exercises.map(x=>`<option value="${x.id}">${h(tx(x.name))}</option>`).join('')}</select></label><div class="form-grid">${[['load',b('负重 kg','Load kg'),0,1000,'0.1'],['sets',b('组数','Sets'),1,100,'1'],['reps',b('每组次数','Reps per set'),1,200,'1'],['rir','RIR',0,20,'0.5'],['duration',b('时长 分钟','Duration minutes'),1,600,'1'],['rpe',b('整节主观强度 0–10','Session RPE 0–10'),0,10,'0.5']].map(([name,t,min,max,step])=>`<label>${h(t)}<input name="${name}" type="number" min="${min}" max="${max}" step="${step}"></label>`).join('')}</div></details><label class="checkline"><input type="checkbox" name="eligible" required>${h(b('我符合上述记录适用条件；不将指标当作医学诊断。','I meet the tracker conditions above and will not use these values as medical diagnoses.'))}</label><label class="checkline"><input type="checkbox" name="consent" required>${h(b('允许把这条记录保存在此浏览器；共用设备上其他人可能看到。','Allow this record to be saved in this browser; others using a shared device may see it.'))}</label><div class="form-buttons"><button type="submit" class="primary">${h(b('保存本地记录','Save locally'))}</button><button type="button" id="calc-metrics" class="secondary">${h(b('只计算，不保存','Calculate only'))}</button></div><div id="metric-message" aria-live="polite"></div></form><div><section class="panel"><h2>${h(b('读取结果，不制造结论','Read values, not diagnoses'))}</h2><div id="metric-calculation"><p class="muted">${h(b('填入体重与身高可计算BMI；填入时长与整节RPE可算记录用负荷代理值。','Enter weight and height for BMI, or duration and session RPE for a logging proxy.'))}</p></div>${sourceLinks(['cdc-bmi','bia-2021','resistance-obesity'])}<p class="small muted">${h(b('时长×整节RPE为本项目展示的粗略负荷代理，任意单位；不是消耗热量、伤病预测或医疗恢复评分。','Duration × session RPE is a rough logging proxy in arbitrary units, not calories, injury prediction or a medical recovery score.'))}</p></section><section class="panel"><h2>${h(b('数据在你手里','Your data stays with you'))}</h2><p>${h(b('无需账号，不发送分析事件。健康记录只有勾选同意并保存时才写入浏览器。清空仅删除本项目记录，不影响语言与主题。','No account or analytics events. Health records are written only after consent and Save. Clearing removes this project’s logs, not language/theme preferences.'))}</p><div class="form-buttons"><button class="secondary" id="export-logs">${h(b('导出 JSON','Export JSON'))}</button><button class="danger-button" id="clear-logs">${h(b('删除全部记录','Delete all records'))}</button></div></section></div></div><section id="metric-history"></section>`;
  const form=$('#metric-form');
  function calculate(data){const a=Number(data.get('metricAge'));if(!Number.isFinite(a)||a<20||a>120||!data.get('eligible'))throw new Error(b('请确认年龄及记录适用条件。','Confirm age and eligibility conditions.'));
    let out='';if(data.get('weight')&&data.get('height'))out+=`<div class="metric-big">${bmi(data.get('weight'),data.get('height')).toFixed(1)}<span>BMI · kg/m²</span></div>`;
    const proxy=sessionLoad(data.get('duration'),data.get('rpe'));if(proxy!==null)out+=`<div class="metric-big">${proxy.toFixed(0)}<span>${h(b('时长 × 整节 RPE · 任意单位','Duration × session RPE · arbitrary units'))}</span></div>`;
    $('#metric-calculation').innerHTML=out||`<p>${h(b('没有足够输入可计算；仍可保存有效的其他记录。','Not enough inputs to calculate; other valid fields can still be logged.'))}</p>`;
  }
  $('#calc-metrics').onclick=()=>{try{calculate(new FormData(form));$('#metric-message').textContent='';}catch(e){$('#metric-message').textContent=e.message;}};
  form.onsubmit=e=>{e.preventDefault();const data=new FormData(form);try{calculate(data);const result=validateLog(Object.fromEntries(data));if(!result.valid)throw new Error(b('请检查这些字段：','Check these fields: ')+result.errors.join(', '));if(!data.get('consent'))throw new Error(b('需要本地保存同意。','Local-storage consent is required.'));const logs=getLogs();if(logs.length>=3000)throw new Error(b('已达3000条上限，请先导出并整理。','Limit of 3,000 records reached. Export and organize first.'));logs.push(result.record);if(!writeStorage(storage,'lift-atlas:logs',logs))throw new Error(b('浏览器拒绝存储，记录没有保存。可改用允许本地存储的浏览器。','Browser storage was denied; the record was not saved.'));$('#metric-message').textContent=b('已保存在当前浏览器。','Saved in this browser.');metricHistory();}catch(err){$('#metric-message').textContent=err.message;}};
  $('#export-logs').onclick=()=>download('lift-atlas-private-logs.json',JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),records:getLogs()},null,2),'application/json');
  $('#clear-logs').onclick=()=>{if(window.confirm(b('删除此浏览器内本项目的全部健康记录？此操作无法撤销。','Delete all this project’s health records in this browser? This cannot be undone.'))){try{storage.removeItem('lift-atlas:logs');metricHistory();flash(b('本地记录已删除。','Local records deleted.'));}catch{flash(b('删除失败，请检查浏览器存储权限。','Delete failed; check browser storage permissions.'));}}};metricHistory();
}
function metricHistory(){const logs=getLogs();const s=weightSummary(logs);const chart=s.days.slice(-30);let plot='';
  if(chart.length){const width=700,height=230,min=Math.min(...chart.map(x=>x.weight)),max=Math.max(...chart.map(x=>x.weight)),range=Math.max(max-min,2);const start=Date.parse(chart[0].date),end=Date.parse(chart.at(-1).date);const point=x=>[40+(Date.parse(x.date)-start)/Math.max(end-start,86400000)*620,185-(x.weight-(min+max-range)/2)/range*145];plot=`<svg class="weight-chart" viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="chart-title"><title id="chart-title">${h(b('体重记录，公斤；横轴为实际日期间隔，不对缺测插值。','Weight records in kilograms; actual date spacing, no imputed missing observations.'))}</title><path class="axis" d="M40 25v175h620"/><polyline class="trend-line" points="${chart.map(x=>point(x).join(',')).join(' ')}"/>${chart.map(x=>{const [px,py]=point(x);return `<circle class="trend-point" cx="${px}" cy="${py}" r="4"><title>${h(x.date)}: ${x.weight.toFixed(1)} kg</title></circle>`;}).join('')}<text x="40" y="222">${chart[0].date}</text><text x="660" y="222" text-anchor="end">${chart.at(-1).date}</text><text x="6" y="18">kg</text><text x="2" y="44">${((min+max+range)/2).toFixed(1)}</text><text x="2" y="189">${((min+max-range)/2).toFixed(1)}</text></svg>`;}
  $('#metric-history').innerHTML=`<div class="inline-heading"><h2>${h(b('本地历史','Local history'))}</h2><span>${logs.length} ${h(b('条','records'))}</span></div><div class="stats-grid"><div><strong>${s.average===null?'—':s.average.toFixed(1)}</strong><span>${h(b('最近7日可用均值 · kg','Available 7-day mean · kg'))}</span></div><div><strong>${s.count}/7</strong><span>${h(b('实际有体重记录的天数','Days with weight data'))}</span></div><div><strong>${s.delta===null?'—':(s.delta>0?'+':'')+s.delta.toFixed(1)}</strong><span>${h(b('与前一7日均值之差 · kg','Difference vs prior 7-day mean · kg'))}</span></div><div><strong>${s.previousCount}/7</strong><span>${h(b('前一窗口样本天数','Days in previous window'))}</span></div></div><p class="small muted">${h(b('窗口以今天为准。至少各3天数据才显示两窗口差；这是展示规则，不是统计显著性或减脂判定。同一天多个测量先取当日均值。','Windows are anchored to today. Differences require at least three days in each window: a display rule, not statistical significance or proof of fat loss. Multiple daily weights are averaged first.'))}</p>${plot}${logs.length?`<div class="table-wrap"><table><thead><tr>${[b('日期','Date'),b('体重 kg','Weight kg'),b('腰围 cm','Waist cm'),b('动作','Exercise'),b('负重 / 组 / 次 / RIR','Load / sets / reps / RIR'),b('时长 / RPE','Minutes / RPE'),b('睡眠 h','Sleep h')].map(t=>`<th>${h(t)}</th>`).join('')}</tr></thead><tbody>${logs.slice(-30).reverse().map(r=>`<tr><td>${h(r.date)}</td><td>${r.weight??'—'}</td><td>${r.waist??'—'}</td><td>${h(r.exercise?(exr(r.exercise)?tx(exr(r.exercise).name):r.exercise):'—')}</td><td>${[r.load,r.sets,r.reps,r.rir].map(v=>v??'—').join(' / ')}</td><td>${r.duration??'—'} / ${r.rpe??'—'}</td><td>${r.sleepHours??'—'}</td></tr>`).join('')}</tbody></table></div>`:notice(b('尚无本地记录。','No local records yet.'))}`;
}
function search(){const q=state.query;const equip=searchItems(D.equipment,q,16),cards=searchItems(D.knowledge,q,12),intent=queryIntent(q);const planMatches=searchItems(D.plans,q,8);let candidates=intent.goal?D.plans.filter(p=>p.goal===intent.goal):planMatches;const risk=textRisk(q);
  $('#main').innerHTML=sectionHead('SEARCH THE ATLAS',b('搜索结果','Search results'),q||b('输入一个词，找到器材、计划和解释。','Enter a term to find equipment, plans and explanations.'))+(risk!=='none'?notice(gateMessage({status:risk==='urgent'?'urgent':'review',reason:risk==='urgent'?'urgent':'query'}),risk==='urgent'?'danger':'warn'):'')+`<div class="two-columns"><section><div class="inline-heading"><h2>${h(tr('equipment'))}</h2><span>${equip.length}</span></div><div class="search-list">${equip.map(e=>`<a href="#equipment/${e.id}"><span class="mini-art">${svg(e.category)}</span><span><strong>${h(tx(e.name))}</strong><small>${h(tx(e.use))}</small></span><span>↗</span></a>`).join('')||empty()}</div></section><section><div class="inline-heading"><h2>${h(tr('knowledge'))}</h2><span>${cards.length}</span></div><div class="knowledge-grid single">${cards.map(knowledgeCard).join('')||empty()}</div></section></div><section><div class="inline-heading"><h2>${h(tr('plans'))}</h2><a href="#plans">${h(tr('start'))} →</a></div>${risk==='none'?notice(b('下面只检索公开模板，尚未考虑你的安全与器材条件。请点击“匹配我的计划”完成筛查。','Below are public template search results, not yet screened for your safety or equipment. Use Find my plan to complete screening.'))+`<div class="plan-grid">${candidates.slice(0,6).map(p=>planCard(p)).join('')||empty()}</div>`:notice(b('当前查询触发安全分流，隐藏计划检索结果。','This query triggers safety routing; plan search results are hidden.'))}</section>`;bindKnowledge();
}
function renderPage(){const parts=location.hash.slice(1).split('/');const page=parts[0]||'home';let id='';try{id=decodeURIComponent(parts[1]||'');}catch{}
  const routes={home,equipment,compare,plans,knowledge,methods,populations,metrics,evidence,search};
  if(page==='equipment'&&id)equipmentDetail(id);else if(page==='plans'&&id)planDetail(id);else if(routes[page])routes[page]();else $('#main').innerHTML=empty(b('页面不存在，请使用导航。','Page not found; use navigation.'));
  document.title=(tr(page)!==page?tr(page):'Lift Atlas')+' · Lift Atlas';
}
function render(){layerNames={foundation:b('通识与目标','Foundations'),training:b('抗阻与有氧','Training'),nutrition:b('营养与体重管理','Nutrition'),metrics:b('测量与解释','Measurement'),recovery:b('疲劳与恢复','Recovery'),rehab:b('损伤与康复边界','Rehabilitation boundaries'),population:b('人群适配','Population adaptation')};shell();renderPage();}
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
render();
